912	+ * Strip the encrypted snapshot body from a tool-invocation audit payload.
913	+ *
914	+ * Audit events are ordinary rows in `events`, so any generic content read can
915	+ * surface one. The snapshot is a separate, access-controlled artifact (creator
916	+ * or admin/owner, via `getToolInvocationSnapshotForCaller`) and must not ride
917	+ * along on a listing: the ciphertext is up to ~2MB of noise, and
918	+ * `snapshot_sha256` is a digest of the plaintext, which would let any member
919	+ * confirm a guessed request/response by recomputing it.
920	+ *
921	+ * The summary fields (`snapshot_version`, `snapshot_status`, `snapshot_bytes`)
922	+ * stay — they tell a reader a snapshot exists and whether it is retrievable.
923	+ */
924	+
925	+import { AUDIT_SEMANTIC_TYPE } from '../tools/constants';
926	+
927	+const TOOL_INVOCATION_ORIGIN_TYPE = 'tool_invocation';
928	+
929	+export function omitToolInvocationSnapshotBody<T>(
930	+  semanticType: string | null | undefined,
931	+  originType: string | null | undefined,
932	+  payload: T
933	+): T {
934	+  if (
935	+    semanticType !== AUDIT_SEMANTIC_TYPE ||
936	+    originType !== TOOL_INVOCATION_ORIGIN_TYPE ||
937	+    !payload ||
938	+    typeof payload !== 'object' ||
939	+    Array.isArray(payload)
940	+  ) {
941	+    return payload;
942	+  }
943	+  const record = payload as Record<string, unknown>;
944	+  if (
945	+    !Object.hasOwn(record, 'snapshot_ciphertext') &&
946	+    !Object.hasOwn(record, 'snapshot_sha256')
947	+  ) {
948	+    return payload;
949	+  }
950	+  const summary = { ...record };
951	+  delete summary.snapshot_ciphertext;
952	+  delete summary.snapshot_sha256;
953	+  return summary as T;
954	+}
