import { useQuery } from "@tanstack/react-query";
import { API_URL, apiErrorFor, fetchWithTimeout, resolveApiScope } from "./core";

export type ToolInvocationSnapshotResult =
	| {
			status: "ok";
			snapshot: { request: unknown; response: unknown };
	  }
	| { status: "too_large"; bytes: number };

/**
 * Lazily fetch one audit event's exact request/response.
 *
 * Only ever enabled after the user expands the disclosure: the body is fetched
 * on demand, never as part of the Activity list payload.
 */
export function useToolInvocationSnapshot(
	ownerSlug: string | null,
	eventId: number | string,
	enabled: boolean,
) {
	return useQuery({
		queryKey: ["tool-invocation-snapshot", ownerSlug, String(eventId)],
		queryFn: async () => {
			const scope = resolveApiScope(ownerSlug ?? undefined);
			const response = await fetchWithTimeout(
				`${API_URL}/api/${encodeURIComponent(scope.slug)}/audit-events/${encodeURIComponent(String(eventId))}/snapshot`,
				{ credentials: "include" },
			);
			if (!response.ok) throw await apiErrorFor(response);
			return response.json() as Promise<ToolInvocationSnapshotResult>;
		},
		enabled: enabled && !!ownerSlug,
		// The route answers 404 for every "you can't have this" case — not the
		// creator, swept past retention, tool out of scope. Retrying doubles the
		// request count for the outcome that is by far the most likely one.
		retry: false,
		staleTime: Number.POSITIVE_INFINITY,
		gcTime: 5 * 60_000,
	});
}

