/**
 * A snapshot can be up to 2MiB of JSON. Pretty-printing all of it into a
 * wrapping <pre> is what makes the tab janky, so render a bounded head and say
 * how much was withheld — the full body is always a click away in the raw
 * response. (Deliberately NOT `JsonRenderer`: that renders the declarative
 * JSON-UI template DSL, not arbitrary data.)
 */
const SNAPSHOT_RENDER_LIMIT = 100_000;

function SnapshotJson({ value }: { value: unknown }) {
	const text = JSON.stringify(value, null, 2) ?? "null";
	const truncated = text.length > SNAPSHOT_RENDER_LIMIT;
	return (
		<>
			<pre className="max-h-80 overflow-auto whitespace-pre-wrap break-words rounded-md border bg-muted/40 p-3 font-mono text-xs">
				{truncated ? text.slice(0, SNAPSHOT_RENDER_LIMIT) : text}
			</pre>
